    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/directx/wine/quartz/control_tlb_t.o", "dll/directx/wine/quartz/quartz_strmif_r.o", "engine:wine", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:strmiids", "engine:uuid", "engine:c:dxguid", "engine:oldnames", "engine:pseh", "import:ddraw", "import:dsound", "import:msacm32", "import:msvfw32", "import:ole32", "import:oleaut32", "import:rpcrt4", "import:user32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:winmm", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "body"],
        "x86_64" => &["dll/directx/wine/quartz/control_tlb_t.o", "dll/directx/wine/quartz/quartz_strmif_r.o", "engine:wine", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:strmiids", "engine:uuid", "engine:c:dxguid", "engine:oldnames", "engine:pseh", "import:ddraw", "import:dsound", "import:msacm32", "import:msvfw32", "import:ole32", "import:oleaut32", "import:rpcrt4", "import:user32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:winmm", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        "aarch64" => &["dll/directx/wine/quartz/control_tlb_t.o", "dll/directx/wine/quartz/quartz_strmif_r.o", "engine:wine", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:strmiids", "engine:uuid", "engine:c:dxguid", "engine:oldnames", "engine:pseh", "import:ddraw", "import:dsound", "import:msacm32", "import:msvfw32", "import:ole32", "import:oleaut32", "import:rpcrt4", "import:user32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:winmm", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/quartz",
        "dll/directx/wine/quartz",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "ENTRY_PREFIX=QUARTZ_",
        "PROXY_DELEGATION",
        "WINE_REGISTER_DLL",
        "WINVER=0x600",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("quartz_shims", &["dll/directx/wine/quartz/acmwrapper.c", "dll/directx/wine/quartz/avidec.c", "dll/directx/wine/quartz/decoder.c", "dll/directx/wine/quartz/dsoundrender.c", "dll/directx/wine/quartz/filesource.c", "dll/directx/wine/quartz/filtergraph.c", "dll/directx/wine/quartz/filtermapper.c", "dll/directx/wine/quartz/main.c", "dll/directx/wine/quartz/memallocator.c", "dll/directx/wine/quartz/parser.c", "dll/directx/wine/quartz/passthrough.c", "dll/directx/wine/quartz/systemclock.c", "dll/directx/wine/quartz/videorenderer.c", "dll/directx/wine/quartz/vmr7.c", "dll/directx/wine/quartz/vmr7_presenter.c", "dll/directx/wine/quartz/vmr9.c", "dll/directx/wine/quartz/window.c", "dll/directx/wine/quartz/proxy.dlldata.c", "dll/directx/wine/quartz/quartz_strmif_p.c"])
        .rc("dll/directx/wine/quartz/quartz.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/quartz/quartz.spec", "quartz.dll")
        .delay_import_lib("dll/directx/wine/ddraw/ddraw.spec", "ddraw.dll", "ddraw")
        .import_lib("dll/directx/wine/dsound/dsound.spec", "dsound.dll", "dsound")
        .import_lib("dll/win32/msacm32/msacm32.spec", "msacm32.dll", "msacm32")
        .import_lib("dll/win32/msvfw32/msvfw32.spec", "msvfw32.dll", "msvfw32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
